import java.util.Arrays;

public class LifeStepperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static boolean[][] blinker() {
        return new boolean[][] {
            {false, false, false},
            {true, true, true},
            {false, false, false}
        };
    }

    public static void main(String[] args) {
        try {
            check("liveNeighbours(blinker, 1, 1)", 2, LifeStepper.liveNeighbours(blinker(), 1, 1));
            check("liveNeighbours(blinker, 0, 0) clamps at the edge", 2,
                    LifeStepper.liveNeighbours(blinker(), 0, 0));
            check("liveNeighbours(blinker, 1, 0)", 1, LifeStepper.liveNeighbours(blinker(), 1, 0));

            check("blinker flips to vertical",
                    "[[false, true, false], [false, true, false], [false, true, false]]",
                    Arrays.deepToString(LifeStepper.step(blinker())));

            boolean[][] block = {{true, true}, {true, true}};
            check("2x2 block is a still life", "[[true, true], [true, true]]",
                    Arrays.deepToString(LifeStepper.step(block)));

            boolean[][] empty3x3 = new boolean[3][3];
            check("empty grid stays empty",
                    "[[false, false, false], [false, false, false], [false, false, false]]",
                    Arrays.deepToString(LifeStepper.step(empty3x3)));

            check("grid with no rows", "[]", Arrays.deepToString(LifeStepper.step(new boolean[0][])));

            boolean[][] original = blinker();
            LifeStepper.step(original);
            check("input grid untouched",
                    "[[false, false, false], [true, true, true], [false, false, false]]",
                    Arrays.deepToString(original));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

