public class LifeStepper {

    public static int liveNeighbours(boolean[][] grid, int row, int col) {
        int count = 0;
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) {
                    continue;
                }
                int r = row + dr;
                int c = col + dc;
                if (r >= 0 && r < grid.length && c >= 0 && c < grid[r].length && grid[r][c]) {
                    count++;
                }
            }
        }
        return count;
    }

    public static boolean[][] step(boolean[][] grid) {
        if (grid.length == 0) {
            return new boolean[0][];
        }
        boolean[][] next = new boolean[grid.length][grid[0].length];
        for (int row = 0; row < grid.length; row++) {
            for (int col = 0; col < grid[row].length; col++) {
                int neighbours = liveNeighbours(grid, row, col);
                if (grid[row][col]) {
                    next[row][col] = neighbours == 2 || neighbours == 3;
                } else {
                    next[row][col] = neighbours == 3;
                }
            }
        }
        return next;
    }
}
